I can build you one right here! 🎮💥

You'll need to paste this into a free site — takes 30 seconds:

1. Open **[codepen.io/pen](https://codepen.io/pen)** on your tablet
2. Delete whatever's in the **HTML** box
3. Paste this code in:

```html
<!DOCTYPE html>
<html>
<body>
<canvas id="c"></canvas>
<script>
const c=document.getElementById('c'),x=c.getContext('2d');
let W,H,a=new(window.AudioContext||window.webkitAudioContext)();

function resize(){W=c.width=innerWidth;H=c.height=innerHeight}
resize();onresize=resize;

function boom(vol=1){
  let o=a.createOscillator(),g=a.createGain();
  o.type='sawtooth';
  o.frequency.setValueAtTime(200*vol+50,a.currentTime);
  o.frequency.exponentialRampToValueAtTime(20,a.currentTime+.4);
  g.gain.setValueAtTime(.6*vol,a.currentTime);
  g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.4);
  o.connect(g).connect(a.destination);
  o.start();o.stop(a.currentTime+.45);

  let o2=a.createOscillator(),g2=a.createGain();
  o2.type='square';
  o2.frequency.setValueAtTime(100*vol,a.currentTime);
  o2.frequency.exponentialRampToValueAtTime(5,a.currentTime+.3);
  g2.gain.setValueAtTime(.4*vol,a.currentTime);
  g2.gain.exponentialRampToValueAtTime(.001,a.currentTime+.3);
  o2.connect(g2).connect(a.destination);
  o2.start();o2.stop(a.currentTime+.35);
}

let score=0,lives=5,sp=4,go=false,st=false;
let targets=[],parts=[];
let sx=0,sy=0,t=0;

class T{
  constructor(){
    this.r=25+Math.random()*35;
    this.x=Math.random()*(W-this.r*2)+this.r;
    this.y=-this.r;
    this.sp=sp+Math.random()*3;
    this.h=Math.random()*60+10;
    this.p=0;
    this.pts=Math.round(300/this.r);
  }
  update(){
    this.y+=this.sp;this.p+=.12;
    if(this.y>H+this.r){lives--;if(lives<=0)go=true;return false}
    return true;
  }
  draw(){
    let gl=Math.sin(this.p)*6;
    x.save();x.translate(this.x,this.y);
    x.shadowColor=`hsl(${this.h},100%,60%)`;
    x.shadowBlur=25+gl;
    x.beginPath();x.arc(0,0,this.r+gl,0,Math.PI*2);
    x.fillStyle=`hsl(${this.h},100%,50%)`;x.fill();
    x.shadowBlur=0;
    x.beginPath();x.arc(0,0,this.r*.55,0,Math.PI*2);
    x.fillStyle=`hsl(${this.h},100%,75%)`;x.fill();
    x.restore();
  }
  hit(tx,ty){
    return Math.hypot(tx-this.x,ty-this.y)<this.r+25;
  }
}

function sparks(px,py,col,n=25){
  for(let i=0;i<n;i++){
    let a=Math.random()*Math.PI*2,s=Math.random()*10+3;
    parts.push({x:px,y:py,vx:Math.cos(a)*s,vy:Math.sin(a)*s,
    life:1,dc:.015+Math.random()*.02,col,sz:Math.random()*7+2});
  }
}

function tap(e){
  e.preventDefault();
  if(a.state==='suspended')a.resume();
  if(go){score=0;lives=5;sp=4;go=false;targets=[];parts=[];st=true;return}
  if(!st){st=true;return}

  let tx=e.touches?e.touches[0].clientX:e.clientX;
  let ty=e.touches?e.touches[0].clientY:e.clientY;

  let hit=false;
  for(let i=targets.length-1;i>=0;i--){
    if(targets[i].hit(tx,ty)){
      let tt=targets[i];
      boom(1+Math.random()*.6);
      sparks(tt.x,tt.y,`hsl(${tt.h},100%,60%)`,35);
      score+=tt.pts;sp+=.015;
      targets.splice(i,1);hit=true;
      sx=(Math.random()-.5)*20;
      sy=(Math.random()-.5)*20;
      break;
    }
  }
  if(!hit)sparks(tx,ty,'#fff8',5);
}

c.addEventListener('mousedown',tap);
c.addEventListener('touchstart',tap);

let stT=0;
function loop(){
  x.save();x.translate(sx,sy);

  // bg
  x.fillStyle='#080816';x.fillRect(-20,-20,W+40,H+40);
  for(let i=0;i<80;i++){
    x.fillStyle=`rgba(255,255,255,${.15+Math.sin(t*.01+i)*.15})`;
    x.fillRect((i*137.5)%W,(i*97.3+t*(.5+i%3))%H,1+i%2,1+i%2);
  }

  if(st&&!go){
    stT++;
    if(stT>=Math.max(12,50-sp*4)){targets.push(new T());stT=0}
    targets=targets.filter(t=>t.update());
  }

  parts=parts.filter(p=>{
    p.x+=p.vx;p.y+=p.vy;p.life-=p.dc;
    p.vx*=.97;p.vy*=.97;
    if(p.life>0){
      x.globalAlpha=p.life;
      x.fillStyle=p.col;
      x.fillRect(p.x-p.sz/2,p.y-p.sz/2,p.sz,p.sz);
    }
    return p.life>0;
  });
  x.globalAlpha=1;

  targets.forEach(t=>t.draw());

  sx*=.88;sy*=.88;t++;

  // HUD
  x.fillStyle='#fff';
  x.font='bold 32px monospace';
  x.fillText('💥 '+score,20,55);
  x.font='26px monospace';
  x.fillText('❤️'.repeat(Math.max(0,lives)),20,90);
  x.font='bold 18px monospace';
  x.fillStyle='#f44';
  x.textAlign='right';
  x.fillText('SPEED '+sp.toFixed(1)+'x',W-20,50);
  x.textAlign='left';

  if(!st){
    x.fillStyle='rgba(0,0,0,.75)';x.fillRect(0,0,W,H);
    x.textAlign='center';
    x.fillStyle='#ff6';x.font='bold 56px monospace';
    x.fillText('💥 BOOM 💥',W/2,H/2-70);
    x.fillStyle='#fff';x.font='26px monospace';
    x.fillText('TAP THE TARGETS!',W/2,H/2-10);
    x.fillStyle='#aaa';x.font='20px monospace';
    x.fillText('Tap to start',W/2,H/2+40);
    x.textAlign='left';
  }

  if(go){
    x.fillStyle='rgba(0,0,0,.85)';x.fillRect(0,0,W,H);
    x.textAlign='center';
    x.fillStyle='#f44';x.font='bold 54px monospace';
    x.fillText('💥 GAME OVER',W/2,H/2-40);
    x.fillStyle='#fff';x.font='bold 40px monospace';
    x.fillText('Score: '+score,W/2,H/2+25);
    x.fillStyle='#aaa';x.font='24px monospace';
    x.fillText('TAP TO RESTART',W/2,H/2+75);
    x.textAlign='left';
  }

  x.restore();
  requestAnimationFrame(loop);
}
loop();
</script>
</body>
</html>
```

**What you'll get:**
- 🔊 **Loud explosion sounds** generated from code (no files needed!)
- 🔥 Targets falling fast — tap to destroy them
- 📈 Speed keeps increasing
- 💥 Screen shakes on every boom
- 🎆 Particle explosions everywhere

> **Volume tip:** Turn your tablet volume to **MAX** before playing! The booms are procedurally generated so they'll blast.
